//! `cargo xtask gen-skin-registry` and `check-skin-registry` (plan E7.7.1,
//! the closed token registry).
//!
//! The generator writes the registry's artefacts from
//! `rekindle_skin::generate`: the app's token CSS and TS, the two TUI
//! palettes and the JSON Schema of a token file. Each carries a "generated;
//! do not edit" header in its own comment syntax (the JSON Schema in
//! `$comment`). The check fails when any file on disk differs from what the
//! generator would write now, and when a base's defaults break one of the
//! registry's own contrast constraints.

use std::path::Path;

use anyhow::{anyhow, Context, Result};
use std::collections::BTreeMap;

use rekindle_skin::generate::{json_schema, tokens_css, tokens_ts, tui_palette, HEADER};
use std::fmt::Write as _;

use rekindle_skin::regions::css::{families, family_css, RegionMap};
use rekindle_skin::registry::{constraint_failures, Base, ENTRIES};

/// The generated stylesheet directory: its literals and repeats are the
/// registry's, so the theme-literal and duplication checks skip it and this
/// staleness check guards it.
pub(crate) const GENERATED_STYLES: &str = "src/styles/generated/";

/// One `[regions]` entry's string list `key` (`elements`, `labels`);
/// empty when the entry has none.
fn strings(id: &str, item: &toml_edit::Item, key: &str) -> Result<Vec<String>> {
    let Some(list) = item.as_table_like().and_then(|f| f.get(key)) else {
        return Ok(Vec::new());
    };
    list.as_array()
        .ok_or_else(|| anyhow!("[regions] `{id}`: `{key}` is not an array"))?
        .iter()
        .map(|e| {
            e.as_str()
                .map(str::to_owned)
                .ok_or_else(|| anyhow!("[regions] `{id}`: a `{key}` entry is not a string"))
        })
        .collect()
}

/// The region map's `[regions]`: slot id → the app elements it paints and
/// the children carrying a labelled slot's text.
fn region_elements() -> Result<BTreeMap<String, RegionMap>> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .ok_or_else(|| anyhow!("xtask has no parent directory"))?;
    let text = std::fs::read_to_string(root.join(crate::declared_grounds::MAP))
        .with_context(|| format!("reading {}", crate::declared_grounds::MAP))?;
    let doc: toml_edit::DocumentMut = text.parse().context("parsing the region map")?;
    let table = doc
        .get("regions")
        .and_then(|t| t.as_table_like())
        .ok_or_else(|| anyhow!("{} has no [regions] table", crate::declared_grounds::MAP))?;
    let mut out = BTreeMap::new();
    for (id, item) in table.iter() {
        let elements = strings(id, item, "elements")?;
        if elements.is_empty() {
            return Err(anyhow!("[regions] `{id}` has no `elements = [...]`"));
        }
        let labels = strings(id, item, "labels")?;
        out.insert(id.to_owned(), RegionMap { elements, labels });
    }
    Ok(out)
}

/// The region sheets, from the region map (the repo's, whatever root the
/// files are written under): one components and one a11y sheet per slot
/// family under `src/styles/generated/regions/`, and the two index sheets
/// `global.css` imports (`regions.css`, `regions-a11y.css`), which import
/// them in slot order.
fn region_sheets() -> Result<Vec<(String, String)>> {
    let map = region_elements()?;
    let mut out = Vec::new();
    let mut index = format!("/* {HEADER}\n *\n * The region slots' sheets, one per family (`rekindle-skin::regions`). */\n");
    let mut index_a11y = format!("/* {HEADER}\n *\n * The region slots' sheets under the user's settings, one per family. */\n");
    for family in families() {
        let (components, a11y) = family_css(HEADER, &map, family)
            .map_err(|e| anyhow!("{}: {e}", crate::declared_grounds::MAP))?;
        let _ = writeln!(index, "@import \"./regions/{family}.css\";");
        let _ = writeln!(index_a11y, "@import \"./regions/{family}-a11y.css\";");
        out.push((
            format!("src/styles/generated/regions/{family}.css"),
            components,
        ));
        out.push((
            format!("src/styles/generated/regions/{family}-a11y.css"),
            a11y,
        ));
    }
    out.push(("src/styles/generated/regions.css".to_owned(), index));
    out.push((
        "src/styles/generated/regions-a11y.css".to_owned(),
        index_a11y,
    ));
    Ok(out)
}

/// The Community window's icon names in TS (plan SK17-7a), from
/// `rekindle_types::dto::skin_layout::community_icon`: the one source of the
/// names, which the importers fill `manifest.icons` with and the shell's
/// `SkinGlyph` draws.
fn community_icon_ts() -> String {
    use rekindle_types::dto::skin_layout::community_icon::ALL;
    let mut out = String::from(
        "// Generated by `cargo xtask gen-skin-registry` from `rekindle-types::dto::skin_layout::community_icon` (plan SK17). Do not edit: change the constants and regenerate; `cargo xtask check` fails when this file is stale.\n\n",
    );
    out.push_str(
        "/** A Community window icon a pack may serve (`manifest.icons`, plan SK17-5). */\n",
    );
    out.push_str("export const COMMUNITY_ICONS = [\n");
    for name in ALL {
        let _ = writeln!(out, "  \"{name}\",");
    }
    out.push_str("] as const;\n\n");
    out.push_str("export type CommunityIcon = (typeof COMMUNITY_ICONS)[number];\n");
    out
}

/// Every generated file, relative to the workspace root, with its content.
fn artefacts() -> Result<Vec<(String, String)>> {
    let mut out: Vec<(String, String)> = [
        ("src/styles/generated/tokens.css", tokens_css()),
        ("src/styles/generated/tokens.ts", tokens_ts()),
        (
            "src/styles/generated/community_icon.ts",
            community_icon_ts(),
        ),
        (
            "crates/rekindle-tui/themes/rekindle-dark.toml",
            tui_palette(Base::Dark),
        ),
        (
            "crates/rekindle-tui/themes/rekindle-light.toml",
            tui_palette(Base::Light),
        ),
        (
            "crates/rekindle-skin/schema/tokens.schema.json",
            json_schema(),
        ),
    ]
    .into_iter()
    .map(|(rel, content)| (rel.to_owned(), content))
    .collect();
    out.extend(region_sheets()?);
    Ok(out)
}

/// Writes every artefact under `root`.
pub fn gen_skin_registry(root: &Path) -> Result<()> {
    for (rel, content) in artefacts()? {
        let path = root.join(&rel);
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
        }
        std::fs::write(&path, content).with_context(|| format!("writing {rel}"))?;
        println!("    wrote {rel}");
    }
    Ok(())
}

/// The stale or missing artefacts under `root`, and every broken
/// constraint of the registry's defaults, one line each.
fn problems(root: &Path) -> Vec<String> {
    let mut out = Vec::new();
    let artefacts = match artefacts() {
        Ok(a) => a,
        Err(e) => return vec![format!("{e:#}")],
    };
    for (rel, content) in artefacts {
        match std::fs::read_to_string(root.join(&rel)) {
            Ok(on_disk) if on_disk == content => {}
            Ok(_) => out.push(format!("{rel}: stale")),
            Err(e) => out.push(format!("{rel}: {e}")),
        }
    }
    for base in Base::ALL {
        for failure in constraint_failures(ENTRIES, base) {
            out.push(format!("registry defaults on {}: {failure}", base.key()));
        }
    }
    out
}

/// Fails when a generated file is stale or missing, or a base's defaults
/// break a registry constraint.
pub fn check_skin_registry(root: &Path) -> Result<()> {
    let problems = problems(root);
    if problems.is_empty() {
        return Ok(());
    }
    Err(anyhow!(
        "{}\n    Change `rekindle-skin::registry`, never a generated file, then run \
         `cargo xtask gen-skin-registry`.",
        problems.join("\n    ")
    ))
}

